widget.draw:
function draw(ctx, state, t) {
function fmt(v) { return Math.round(v * 100) / 100; }
function X(x) { return left + (x / 2) * plotW; }
function Y(s) { return baseY - (s / 2) * plotH; }


var w = state.w;
var h = state.h;
var m = state.m;
var v = state.v;
var sq = Math.sqrt(v);
var step = m / sq;
var xR = sq;
var left = 52;
var right = w - 24;
var top = 26;
var baseY = h - 78;
var plotW = right - left;
var plotH = baseY - top;
var N = 60;
var i = 0;
var x = 0;
var s = 0;
var px = 0;
var py = 0;


ctx.clearRect(0, 0, w, h);
ctx.fillStyle = "#f6f3ec";
ctx.fillRect(0, 0, w, h);
ctx.strokeStyle = "#1d1a16";
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(left, baseY);
ctx.lineTo(right, baseY);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(left, baseY);
ctx.lineTo(left, top);
ctx.stroke();
ctx.strokeStyle = "#1f4b99";
ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= N; i++) {
x = (i / N) * 2;
s = x / sq;
px = X(x);
py = Y(s);
if (i === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
}
ctx.stroke();
ctx.strokeStyle = "#c4512c";
ctx.lineWidth = 1.5;
ctx.beginPath();
for (i = 0; i <= 24; i++) {
px = X(xR);
py = baseY - ((i / 24) * (baseY - Y(1)));
if (i === 0) { ctx.moveTo(px, baseY); } else { ctx.lineTo(px, py); }
if (i === 0) { ctx.moveTo(px, py); } else { ctx.moveTo(px, py); }
}
ctx.stroke();
ctx.beginPath();
ctx.moveTo(left, Y(1));
ctx.lineTo(right, Y(1));
ctx.stroke();
px = X(m);
py = Y(step);
ctx.fillStyle = "#1f4b99";
ctx.beginPath();
ctx.arc(px, py, 6, 0, 6.2832);
ctx.fill();
ctx.fillStyle = "#1d1a16";
ctx.font = "12px sans-serif";
ctx.fillText("m = " + fmt(m), 52, h - 56);
ctx.fillText("v = " + fmt(v), 160, h - 56);
ctx.fillText("step = " + fmt(step), 268, h - 56);
ctx.fillText("unit step " + fmt(xR), X(xR) - 88, Y(1) - 10);
ctx.fillText("threshold " + fmt(xR), X(xR) + 8, baseY - 6);
ctx.fillText("m axis 0 to 2", left, baseY + 16);
ctx.fillText("step axis 0 to 2", left, top - 8);
}
